def test_schedule_respects_cap(self):
    # Unseeded on purpose: the cap must hold for *every* jitter draw.
    retrier = Retrier(base=0.5, cap=34, max_attempts=7)
    for delay in retrier.schedule():
        self.assertLessEqual(delay, 34)

def test_cap_holds_at_maximum_jitter(self):
    # Deterministic worst case: attempt 7 is 32s before jitter, and the
    # +10% jitter would make it 35.2s. The cap must win.
    class MaxJitter:
        def uniform(self, lo, hi):
            return hi

    retrier = Retrier(base=0.5, cap=34, max_attempts=7, rng=MaxJitter())
    schedule = retrier.schedule()
    self.assertEqual(schedule[-1], 34)
    for delay in schedule:
        self.assertLessEqual(delay, 34)

def test_jitter_still_applied_below_cap(self):
    class MaxJitter:
        def uniform(self, lo, hi):
            return hi

    delay = compute_delay(1, base=1, cap=100, jitter=0.1, rng=MaxJitter())
    self.assertAlmostEqual(delay, 1.1)

def test_delay_never_negative(self):
    class MinJitter:
        def uniform(self, lo, hi):
            return lo

    delay = compute_delay(1, base=1, cap=100, jitter=1.5, rng=MinJitter())
    self.assertEqual(delay, 0)

